# Helper: generate all integer partitions of n in nonincreasing order
def gen_parts(n, max_part):
    if n == 0:
        yield []
        return
    k = min(n, max_part)
    while k >= 1:
        for rest in gen_parts(n - k, k):
            yield [k] + rest
        k -= 1

# Compute F(n; l, m, s, r, h, t_mod) with added constraints on largest part and ones count
def compute(n, l, m, s, r, h, t_mod, d, c, min_ones, max_ones):
    total = 0
    for part in gen_parts(n, n):
        if not part:
            continue
        # Constraint: largest part congruent to c mod d
        largest = part[0]
        if largest % d != c:
            continue
        # Ones count constraint
        ones = 0
        for x in part:
            if x == 1:
                ones += 1
        if ones < min_ones or ones > max_ones:
            continue
        # multiplicities per distinct part
        mult = {}
        for x in part:
            mult[x] = mult.get(x, 0) + 1
        # Build allowed options per distinct part
        # Each distinct part contributes options: (delta_count_overlined mod s, delta_sum_overlined mod h)
        allowed = []
        invalid = False
        for v, k in mult.items():
            if v % l == 0:
                # If v divisible by l, any non-overlined occurrence is forbidden.
                # Overlining the first occurrence is only valid when k == 1 and v % m != 0.
                if k >= 2:
                    invalid = True
                    break
                if v % m == 0:
                    invalid = True
                    break
                allowed.append([(1 % s, v % h)])
            else:
                # Non-overlined option is allowed
                opts = [(0, 0)]
                # Overlined option allowed only if v not divisible by m
                if v % m != 0:
                    opts.append((1 % s, v % h))
                allowed.append(opts)
        if invalid:
            continue
        # DP over distinct parts for residues modulo s and h
        dp = [[0] * h for _ in range(s)]
        dp[0][0] = 1
        for opts in allowed:
            newdp = [[0] * h for _ in range(s)]
            for i in range(s):
                row = dp[i]
                for j in range(h):
                    val = row[j]
                    if val == 0:
                        continue
                    for (ds, dh) in opts:
                        newdp[(i + ds) % s][(j + dh) % h] += val
            dp = newdp
        total += dp[r % s][t_mod % h]
    return total

